// DogworksTV · lista de jogos co-op/multiplayer
// - Base list: data/games.json (generated by scripts/build-library.mjs).
// - Favorites, added games, edits and hidden games: localStorage (export/import as backup).
// - Steam sign-in, "Eu tenho", who owns each game and prices: Worker API (/api/*) + D1.

const STORAGE_KEY = 'dogworks-games:v1';

const svg = (paths) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths}</svg>`;

const ICON = {
  users: svg('<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>'),
  sofa: svg('<path d="M20 9V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v3"/><path d="M2 11a2 2 0 0 1 4 0v2h12v-2a2 2 0 0 1 4 0v5a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2Z"/><path d="M4 18v2M20 18v2"/>'),
  swords: svg('<path d="M14.5 17.5 3 6V3h3l11.5 11.5M13 19l6-6M16 16l4 4M19 21l2-2"/><path d="M14.5 6.5 18 3h3v3l-3.5 3.5M5 14l4 4M7 17l-3 3M3 19l2 2"/>'),
  crown: svg('<path d="m2 4 3 12h14l3-12-6 7-4-7-4 7-6-7Z"/><path d="M5 20h14"/>'),
  gamepad: svg('<path d="M6 12h4M8 10v4M15 13h.01M18 11h.01"/><rect width="20" height="12" x="2" y="6" rx="2"/>'),
  info: svg('<circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>'),
  star: svg('<polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/>'),
  edit: svg('<path d="M17 3a2.85 2.85 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/>'),
  eyeOff: svg('<path d="M9.88 9.88a3 3 0 1 0 4.24 4.24M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68M6.61 6.61A13.53 13.53 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61M2 2l20 20"/>'),
  eye: svg('<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>'),
  trash: svg('<path d="M3 6h18M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>'),
  close: svg('<path d="M18 6 6 18M6 6l12 12"/>'),
  check: svg('<path d="M20 6 9 17l-5-5"/>'),
  tag: svg('<path d="M12.6 2.6A2 2 0 0 0 11.2 2H4a2 2 0 0 0-2 2v7.2a2 2 0 0 0 .6 1.4l8.7 8.7a2.4 2.4 0 0 0 3.4 0l6.6-6.6a2.4 2.4 0 0 0 0-3.4Z"/><circle cx="7.5" cy="7.5" r=".5"/>'),
  trend: svg('<path d="m22 17-8.5-8.5-5 5L2 7"/><path d="M16 17h6v-6"/>'),
};

const LOGO = (store) => `<span class="logo logo-${store}" aria-hidden="true"></span>`;

const CATEGORIES = [
  { id: 'coop-online', label: 'Co-op online', icon: ICON.users },
  { id: 'coop-local', label: 'Co-op local', icon: ICON.sofa },
  { id: 'pvp', label: 'PvP', title: 'Competitivo (PvP)', icon: ICON.swords },
  { id: 'estrategia', label: 'Estratégia', icon: ICON.crown },
  { id: 'party', label: 'Party', title: 'Party & versus local', icon: ICON.gamepad },
  { id: 'outros', label: 'Outros', title: 'Multiplayer secundário', icon: ICON.info },
];
const CATEGORY_BY_ID = Object.fromEntries(CATEGORIES.map((c) => [c.id, c]));

const TAGS = {
  'coop-online': { label: 'Co-op online' },
  'coop-local': { label: 'Co-op local', cls: 'local' },
  'coop-lan': { label: 'Co-op LAN' },
  'split-screen': { label: 'Tela dividida', cls: 'local' },
  'pvp-online': { label: 'PvP online', cls: 'pvp' },
  'pvp-local': { label: 'PvP local', cls: 'pvp' },
  'pvp-lan': { label: 'PvP LAN', cls: 'pvp' },
  crossplay: { label: 'Crossplay' },
  mmo: { label: 'MMO' },
};

const PLATFORMS = [
  { id: 'steam', label: 'Steam' },
  { id: 'epic', label: 'Epic' },
  { id: 'outra', label: 'Outra' },
];

/* ---------------- helpers ---------------- */

const $ = (sel, root = document) => root.querySelector(sel);

const esc = (s) =>
  String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

const norm = (s = '') =>
  String(s)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[®™©]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const compact = (s) => norm(s).replace(/ /g, '');

function safeUrl(u) {
  if (!u) return '';
  try {
    const url = new URL(u);
    if (url.protocol === 'https:' || url.protocol === 'http:') return url.href;
  } catch {}
  return '';
}

const epicSearchUrl = (name) =>
  `https://store.epicgames.com/pt-BR/browse?q=${encodeURIComponent(name)}&sortBy=relevancy&sortDir=DESC`;

const steamAppId = (url) => (String(url || '').match(/store\.steampowered\.com\/app\/(\d+)/) || [])[1] || null;

// Same game across users: Steam appid when known, else the normalized name.
const gameKey = (g) => {
  const id = steamAppId(g.steamUrl);
  return id ? `steam:${id}` : `name:${compact(g.name).slice(0, 120)}`;
};

// Epic blocks reading its store pages, so an Epic link only gives us the product slug.
// "…/p/borderlands-3" → "borderlands 3", which is then searched on Steam.
function epicLinkInfo(text) {
  const m = String(text || '').match(/epicgames\.com\/(?:[a-z]{2}(?:-[A-Z]{2})?\/)?(?:store\/)?(?:[a-z]{2}(?:-[A-Z]{2})?\/)?(?:p|product)\/([a-z0-9-]+)/i);
  if (!m) return null;
  const slug = m[1].replace(/-[0-9a-f]{6}$/i, '');
  return { url: `https://store.epicgames.com/pt-BR/p/${m[1]}`, name: slug.replace(/-/g, ' ').trim() };
}

const titleCase = (s) => s.replace(/\b\w/g, (c) => c.toUpperCase());

const collator = new Intl.Collator('pt-BR', { sensitivity: 'base', numeric: true });

const formatMoney = (p) =>
  p ? new Intl.NumberFormat('pt-BR', { style: 'currency', currency: p.currency || 'BRL' }).format(p.amount) : '';

/* ---------------- API ---------------- */

async function api(path, { method = 'GET', body } = {}) {
  const res = await fetch(path, {
    method,
    headers: { Accept: 'application/json', ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
    credentials: 'same-origin',
  });
  const type = res.headers.get('content-type') || '';
  if (!type.includes('application/json')) throw new Error('offline');
  const data = await res.json();
  if (!res.ok) throw Object.assign(new Error(data.error || `Erro ${res.status}`), { status: res.status });
  return data;
}

const isOffline = (e) => e.message === 'offline' || e instanceof TypeError;

/* ---------------- storage ---------------- */

const emptyStore = () => ({
  favorites: [],
  custom: [],
  hidden: [],
  overrides: {},
  prefs: { sort: 'name', category: 'all', onlyFav: false, onlyOwned: false },
});

function sanitizeStore(s) {
  const base = emptyStore();
  if (!s || typeof s !== 'object') return base;
  const arr = (v) => (Array.isArray(v) ? v : []);
  return {
    favorites: arr(s.favorites).filter((x) => typeof x === 'string'),
    hidden: arr(s.hidden).filter((x) => typeof x === 'string'),
    custom: arr(s.custom).filter((g) => g && typeof g.id === 'string' && typeof g.name === 'string'),
    overrides: s.overrides && typeof s.overrides === 'object' ? s.overrides : {},
    prefs: { ...base.prefs, ...(s.prefs && typeof s.prefs === 'object' ? s.prefs : {}) },
  };
}

function loadStore() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return sanitizeStore(JSON.parse(raw));
  } catch {}
  return emptyStore();
}

function saveStore() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.store));
  } catch {
    toast('Não deu para salvar neste navegador (modo anônimo?). Exporte um backup.');
  }
}

/* ---------------- state ---------------- */

const state = {
  base: [],
  store: loadStore(),
  q: '',
  showHidden: false,
  editing: null, // { id, source } when editing
  steamExtra: null, // description/genres from the last Steam pick
  detailId: null, // game open in the detail modal
};

const auth = {
  api: true, // false when the site is hosted without the Worker
  user: null,
  manual: [], // [{ key, platform }]
  steamAppids: new Set(),
  counts: {}, // key -> number of owners
};

function setMe(data) {
  auth.user = data.user;
  auth.manual = data.owned.manual;
  auth.steamAppids = new Set(data.owned.steamAppids);
}

function myOwnership(g) {
  const key = gameKey(g);
  const platforms = new Set(auth.manual.filter((m) => m.key === key).map((m) => m.platform));
  const appid = steamAppId(g.steamUrl);
  const autoSteam = !!(appid && auth.steamAppids.has(Number(appid)));
  if (autoSteam) platforms.add('steam');
  return { platforms, autoSteam };
}

function allGames() {
  const { store } = state;
  const favs = new Set(store.favorites);
  const hidden = new Set(store.hidden);
  const base = state.base.map((g) => ({ ...g, ...(store.overrides[g.id] || {}), source: 'base' }));
  const custom = store.custom.map((g) => ({ ...g, source: 'custom' }));
  return [...base, ...custom].map((g) => {
    const game = {
      ...g,
      category: CATEGORY_BY_ID[g.category] ? g.category : 'outros',
      tags: Array.isArray(g.tags) ? g.tags : [],
      genres: Array.isArray(g.genres) ? g.genres : [],
      fav: favs.has(g.id),
      hidden: hidden.has(g.id),
    };
    game.key = gameKey(game);
    game.owned = auth.user ? myOwnership(game).platforms.size > 0 : false;
    game.ownersCount = auth.counts[game.key] || 0;
    return game;
  });
}

const findGame = (id) => allGames().find((g) => g.id === id);

function haystack(g) {
  const tagLabels = g.tags.map((t) => TAGS[t]?.label || '');
  return norm([g.name, g.note, CATEGORY_BY_ID[g.category]?.label, ...g.genres, ...tagLabels].join(' '));
}

function matchesQuery(g, q) {
  if (!q) return true;
  const h = haystack(g);
  return q.split(' ').every((word) => h.includes(word));
}

function sortGames(list) {
  const sort = state.store.prefs.sort;
  return list.sort((a, b) => {
    if (sort === 'fav' && a.fav !== b.fav) return a.fav ? -1 : 1;
    if (sort === 'owners' && a.ownersCount !== b.ownersCount) return b.ownersCount - a.ownersCount;
    if (sort === 'recent' && (a.addedAt || 0) !== (b.addedAt || 0)) return (b.addedAt || 0) - (a.addedAt || 0);
    return collator.compare(a.name, b.name);
  });
}

/* ---------------- rendering: grid ---------------- */

const main = $('#main');

function tagsHtml(g, max = 5) {
  const specific = g.tags.filter((t) => TAGS[t]);
  const tags = specific.map((t) => `<span class="tag ${TAGS[t].cls || ''}">${TAGS[t].label}</span>`);
  if (!tags.length && g.tags.includes('multiplayer')) tags.push('<span class="tag">Multijogador</span>');
  return tags.slice(0, max).join('');
}

function storeLinksHtml(g, withLabel = false) {
  const steam = safeUrl(g.steamUrl);
  const epic = safeUrl(g.epicUrl) || epicSearchUrl(g.name);
  return `
    ${steam ? `<a class="store-link steam${withLabel ? ' with-label' : ''}" href="${esc(steam)}" target="_blank" rel="noopener" title="Ver na Steam" aria-label="Ver ${esc(g.name)} na Steam">${LOGO('steam')}${withLabel ? 'Steam' : ''}</a>` : ''}
    <a class="store-link epic${withLabel ? ' with-label' : ''}" href="${esc(epic)}" target="_blank" rel="noopener" title="Ver na Epic Games Store" aria-label="Ver ${esc(g.name)} na Epic Games Store">${LOGO('epic')}${withLabel ? 'Epic' : ''}</a>`;
}

function cardHtml(g) {
  const img = safeUrl(g.image);
  return `
  <article class="card${g.fav ? ' is-fav' : ''}${g.hidden ? ' is-hidden' : ''}" data-id="${esc(g.id)}">
    <div class="card-media">
      ${img ? `<img src="${esc(img)}" alt="" loading="lazy" decoding="async">` : `<span class="placeholder">${esc(g.name)}</span>`}
      <div class="badges">
        ${g.owned ? `<span class="badge badge-owned">${ICON.check}Você tem</span>` : ''}
        ${g.ownersCount ? `<span class="badge" title="${g.ownersCount} ${g.ownersCount === 1 ? 'pessoa tem' : 'pessoas têm'} este jogo">${ICON.users}${g.ownersCount}</span>` : ''}
        ${g.source === 'custom' ? '<span class="badge badge-custom">Adicionado</span>' : ''}
        ${g.hidden ? '<span class="badge">Oculto</span>' : ''}
      </div>
      <button class="fav-btn" type="button" data-action="fav" aria-pressed="${g.fav}"
        aria-label="${g.fav ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}: ${esc(g.name)}">${ICON.star}</button>
    </div>
    <div class="card-body">
      <h3 class="card-title"><button type="button" class="card-open" data-action="open">${esc(g.name)}</button></h3>
      ${g.note ? `<p class="card-note">${esc(g.note)}</p>` : ''}
      <div class="tags">${tagsHtml(g)}</div>
      <div class="card-footer">
        ${storeLinksHtml(g)}
        <span class="card-tools">
          <button class="icon-btn" type="button" data-action="edit" title="Editar" aria-label="Editar ${esc(g.name)}">${ICON.edit}</button>
          ${
            g.source === 'custom'
              ? `<button class="icon-btn" type="button" data-action="remove" title="Remover" aria-label="Remover ${esc(g.name)}">${ICON.trash}</button>`
              : `<button class="icon-btn" type="button" data-action="hide" title="${g.hidden ? 'Mostrar' : 'Ocultar'}" aria-label="${g.hidden ? 'Mostrar' : 'Ocultar'} ${esc(g.name)}">${g.hidden ? ICON.eye : ICON.eyeOff}</button>`
          }
        </span>
      </div>
    </div>
  </article>`;
}

function render() {
  const { prefs } = state.store;
  const q = norm(state.q);
  const games = allGames();
  const onlyOwned = prefs.onlyOwned && !!auth.user;

  const pool = games.filter(
    (g) =>
      (state.showHidden || !g.hidden) &&
      (!prefs.onlyFav || g.fav) &&
      (!onlyOwned || g.owned) &&
      matchesQuery(g, q),
  );

  renderChips(pool);
  renderStats(games);

  const visible = sortGames(pool.filter((g) => prefs.category === 'all' || g.category === prefs.category));

  if (!visible.length) {
    let msg = 'Nenhum jogo encontrado com esses filtros.';
    if (prefs.onlyFav && !games.some((g) => g.fav)) msg = 'Você ainda não marcou favoritos. Clique na ★ de um jogo.';
    else if (onlyOwned && !games.some((g) => g.owned)) msg = 'Você ainda não marcou nenhum jogo como seu. Abra um jogo e use “Eu tenho”.';
    main.innerHTML = `
      <div class="empty">
        <img src="assets/logo.png" alt="">
        <strong>Nada por aqui</strong>
        ${msg}
      </div>`;
    return;
  }

  const groups = CATEGORIES.map((c) => ({ ...c, games: visible.filter((g) => g.category === c.id) })).filter(
    (c) => c.games.length,
  );

  main.innerHTML = groups
    .map(
      (c) => `
      <section class="group" aria-labelledby="h-${c.id}">
        <div class="panel">
          <span class="panel-icon">${c.icon}</span>
          <h2 class="panel-title" id="h-${c.id}">${esc(c.title || c.label)}
            <span class="panel-count">${c.games.length} ${c.games.length === 1 ? 'jogo' : 'jogos'}</span>
          </h2>
        </div>
        <div class="grid">${c.games.map(cardHtml).join('')}</div>
      </section>`,
    )
    .join('');
}

function renderChips(pool) {
  const { category } = state.store.prefs;
  const count = (id) => (id === 'all' ? pool.length : pool.filter((g) => g.category === id).length);
  const chips = [{ id: 'all', label: 'Todos' }, ...CATEGORIES];
  $('#chips').innerHTML = chips
    .map(
      (c) => `<button class="chip" type="button" role="tab" data-category="${c.id}" aria-selected="${category === c.id}">
        ${esc(c.label)} <span class="count">${count(c.id)}</span></button>`,
    )
    .join('');
}

function renderStats(games) {
  const shown = games.filter((g) => !g.hidden);
  const favs = shown.filter((g) => g.fav).length;
  const custom = shown.filter((g) => g.source === 'custom').length;
  const owned = shown.filter((g) => g.owned).length;
  const hidden = games.length - shown.length;
  $('#stats').innerHTML =
    `<strong>${shown.length}</strong> jogos · <strong>${favs}</strong> favoritos` +
    (auth.user ? ` · você tem <strong>${owned}</strong>` : '') +
    (custom ? ` · <strong>${custom}</strong> adicionados por você` : '');
  $('#hidden-count').textContent = hidden ? `${hidden} ${hidden === 1 ? 'jogo oculto' : 'jogos ocultos'}` : 'Nenhum jogo oculto';
}

function syncToolbar() {
  const { prefs } = state.store;
  $('#sort').value = prefs.sort;
  $('#btn-only-fav').setAttribute('aria-pressed', String(!!prefs.onlyFav));
  $('#btn-only-owned').setAttribute('aria-pressed', String(!!prefs.onlyOwned));
  $('#btn-only-owned').hidden = !auth.user;
  $('#sort-owners').hidden = !auth.api;
}

/* ---------------- rendering: account ---------------- */

function renderAccount() {
  const slot = $('#account');
  const panel = $('#account-panel');
  if (!auth.api) {
    slot.innerHTML = '';
    panel.innerHTML = '';
    return;
  }
  if (!auth.user) {
    slot.innerHTML = `<a class="btn btn-steam" href="/api/auth/login">${LOGO('steam')}<span>Entrar com Steam</span></a>`;
    panel.innerHTML = `
      <div class="account-card">
        <p>Entre com a Steam para marcar os jogos que você tem e ver quem mais tem cada jogo.</p>
        <a class="btn btn-steam" href="/api/auth/login">${LOGO('steam')}Entrar com Steam</a>
      </div>`;
    return;
  }
  const u = auth.user;
  const avatar = safeUrl(u.avatar);
  slot.innerHTML = `
    <button class="btn btn-ghost btn-user" type="button" id="btn-user" aria-label="Sua conta: ${esc(u.name)}">
      ${avatar ? `<img src="${esc(avatar)}" alt="" width="24" height="24">` : ''}
      <span class="hide-sm">${esc(u.name)}</span>
    </button>`;
  const synced = u.librarySyncedAt ? new Date(u.librarySyncedAt).toLocaleString('pt-BR') : '—';
  panel.innerHTML = `
    <div class="account-card">
      <div class="account-head">
        ${avatar ? `<img src="${esc(avatar)}" alt="" width="48" height="48">` : ''}
        <div>
          <strong>${esc(u.name)}</strong>
          <a href="${esc(safeUrl(u.profileUrl))}" target="_blank" rel="noopener">Perfil Steam</a>
        </div>
      </div>
      <p class="hint ${u.libraryVisible ? '' : 'warn'}">
        ${
          u.libraryVisible
            ? `Biblioteca Steam detectada: <strong>${auth.steamAppids.size}</strong> jogos. Atualizada em ${synced}.`
            : 'Não consegui ler sua biblioteca Steam. Deixe “Detalhes de jogos” como <strong>Público</strong> na privacidade do perfil Steam e sincronize, ou marque os jogos à mão.'
        }
      </p>
      <div class="account-actions">
        <button class="btn btn-ghost" type="button" id="btn-sync">Sincronizar biblioteca</button>
        <button class="btn btn-ghost" type="button" id="btn-logout">Sair</button>
      </div>
    </div>`;
}

/* ---------------- toast ---------------- */

let toastTimer;
function toast(message, action) {
  const el = $('#toast');
  el.innerHTML = '';
  el.append(message);
  if (action) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'toast-action';
    btn.textContent = action.label;
    btn.onclick = () => {
      action.run();
      el.hidden = true;
    };
    el.append(btn);
  }
  el.hidden = false;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => (el.hidden = true), action ? 6000 : 3000);
}

/* ---------------- local actions (favorite, hide, remove, edit) ---------------- */

function toggleList(list, id) {
  const i = list.indexOf(id);
  if (i >= 0) list.splice(i, 1);
  else list.push(id);
  return i < 0;
}

function refreshAll() {
  render();
  if (state.detailId && dlgDetail.open) renderDetail(false);
}

function runAction(action, id) {
  const game = findGame(id);
  if (!game) return;
  const { store } = state;

  switch (action) {
    case 'open':
      openDetail(id);
      break;
    case 'fav': {
      const added = toggleList(store.favorites, id);
      saveStore();
      refreshAll();
      toast(added ? `★ ${game.name} nos favoritos` : `${game.name} saiu dos favoritos`);
      break;
    }
    case 'hide': {
      const hid = toggleList(store.hidden, id);
      saveStore();
      if (hid && dlgDetail.open) dlgDetail.close();
      refreshAll();
      if (hid) {
        toast(`${game.name} foi ocultado`, {
          label: 'Desfazer',
          run: () => {
            toggleList(store.hidden, id);
            saveStore();
            refreshAll();
          },
        });
      }
      break;
    }
    case 'remove': {
      const idx = store.custom.findIndex((g) => g.id === id);
      if (idx < 0) return;
      const [removed] = store.custom.splice(idx, 1);
      const wasFav = store.favorites.includes(id);
      store.favorites = store.favorites.filter((f) => f !== id);
      saveStore();
      if (dlgDetail.open) dlgDetail.close();
      render();
      toast(`${game.name} removido`, {
        label: 'Desfazer',
        run: () => {
          store.custom.splice(idx, 0, removed);
          if (wasFav) store.favorites.push(id);
          saveStore();
          render();
        },
      });
      break;
    }
    case 'edit':
      if (dlgDetail.open) dlgDetail.close();
      openGameDialog(game);
      break;
  }
}

main.addEventListener('click', (e) => {
  const card = e.target.closest('.card');
  if (!card) return;
  const btn = e.target.closest('[data-action]');
  if (btn) return runAction(btn.dataset.action, card.dataset.id);
  if (e.target.closest('a')) return; // store links
  runAction('open', card.dataset.id);
});

// Broken image → name placeholder
function imageFallback(e) {
  const img = e.target;
  if (img.tagName !== 'IMG' || img.closest('.btn-user, .account-head, .owner')) return;
  const span = document.createElement('span');
  span.className = 'placeholder';
  span.textContent = img.dataset.name || img.closest('.card')?.querySelector('.card-title')?.textContent || '';
  img.replaceWith(span);
}
main.addEventListener('error', imageFallback, true);

/* ---------------- detail modal ---------------- */

const dlgDetail = $('#dlg-detail');
const detailEl = $('#detail');
const priceCache = new Map();

function openDetail(id) {
  state.detailId = id;
  renderDetail(true);
  if (!dlgDetail.open) dlgDetail.showModal();
}

dlgDetail.addEventListener('close', () => (state.detailId = null));
dlgDetail.addEventListener('click', (e) => {
  if (e.target === dlgDetail || e.target.closest('[data-close]')) return dlgDetail.close();
  const btn = e.target.closest('[data-action]');
  if (btn && state.detailId) runAction(btn.dataset.action, state.detailId);
  const own = e.target.closest('[data-platform]');
  if (own) toggleOwnership(own);
});
detailEl.addEventListener('error', imageFallback, true);

function renderDetail(loadRemote) {
  const g = findGame(state.detailId);
  if (!g) return dlgDetail.close();
  const img = safeUrl(g.image);
  const cat = CATEGORY_BY_ID[g.category];
  const prevScroll = loadRemote ? 0 : $('.detail-body', detailEl)?.scrollTop || 0;

  detailEl.innerHTML = `
    <div class="detail-hero">
      ${img ? `<img src="${esc(img)}" alt="" data-name="${esc(g.name)}">` : `<span class="placeholder">${esc(g.name)}</span>`}
      <button class="fav-btn" type="button" data-action="fav" aria-pressed="${g.fav}"
        aria-label="${g.fav ? 'Remover dos favoritos' : 'Adicionar aos favoritos'}">${ICON.star}</button>
      <button class="icon-btn detail-close" type="button" data-close aria-label="Fechar">${ICON.close}</button>
    </div>
    <div class="detail-body">
      <div class="detail-head">
        <span class="detail-cat">${cat.icon}${esc(cat.title || cat.label)}</span>
        <h2 class="detail-title" id="detail-title">${esc(g.name)}</h2>
        ${g.note ? `<p class="card-note">${esc(g.note)}</p>` : ''}
        <div class="tags">${tagsHtml(g, 9)}</div>
        ${g.genres.length ? `<p class="detail-genres">${esc(g.genres.join(' · '))}</p>` : ''}
      </div>
      ${g.description ? `<p class="detail-desc">${esc(g.description)}</p>` : ''}

      <section class="detail-section" aria-labelledby="sec-prices">
        <h3 class="section-title" id="sec-prices">${ICON.tag}Preços</h3>
        <div class="prices" id="detail-prices">${pricesHtml(g, priceCache.get(g.key))}</div>
      </section>

      ${
        auth.api
          ? `<section class="detail-section" aria-labelledby="sec-own">
              <h3 class="section-title" id="sec-own">${ICON.check}Eu tenho</h3>
              <div id="detail-own">${ownHtml(g)}</div>
            </section>
            <section class="detail-section" aria-labelledby="sec-owners">
              <h3 class="section-title" id="sec-owners">${ICON.users}Quem tem <span class="section-count" id="owners-count"></span></h3>
              <ul class="owners" id="detail-owners"><li class="hint">Carregando…</li></ul>
            </section>`
          : ''
      }
    </div>
    <div class="dialog-footer detail-footer">
      <div class="detail-stores">${storeLinksHtml(g, true)}</div>
      <button class="btn btn-ghost" type="button" data-action="edit">${ICON.edit}Editar</button>
      ${
        g.source === 'custom'
          ? `<button class="btn btn-ghost" type="button" data-action="remove">${ICON.trash}Remover</button>`
          : `<button class="btn btn-ghost" type="button" data-action="hide">${g.hidden ? ICON.eye : ICON.eyeOff}${g.hidden ? 'Mostrar' : 'Ocultar'}</button>`
      }
    </div>`;

  $('.detail-body', detailEl).scrollTop = prevScroll;
  if (loadRemote || !priceCache.has(g.key)) loadPrices(g);
  if (auth.api) loadOwners(g);
}

/* prices */

function priceCardHtml(store, label, url, info, itadEnabled) {
  let body;
  if (!info) {
    body =
      store === 'epic' && !itadEnabled
        ? '<span class="price-muted">Ver preço na loja</span>'
        : `<span class="price-muted">${store === 'epic' ? 'Sem preço na Epic' : 'Sem preço'}</span>`;
  } else if (info.free) {
    body = '<span class="price-now">Grátis</span>';
  } else if (info.unavailable || !info.price) {
    body = '<span class="price-muted">Indisponível para compra</span>';
  } else {
    const onSale = info.discount > 0;
    body = `
      <span class="price-now">${formatMoney(info.price)}</span>
      ${onSale ? `<span class="price-old">${formatMoney(info.regular)}</span>` : ''}`;
  }
  const discount = info && info.discount > 0 ? `<span class="discount">-${info.discount}%</span>` : '';
  const low =
    info?.storeLow && info.price && info.storeLow.amount < info.price.amount
      ? `<span class="price-low">Menor na loja: ${formatMoney(info.storeLow)}</span>`
      : info?.storeLow && info.price && info.storeLow.amount >= info.price.amount && info.discount > 0
        ? '<span class="price-low good">Menor preço da loja!</span>'
        : '';
  return `
    <a class="price-card ${store}${info && info.discount > 0 ? ' on-sale' : ''}" href="${esc(url)}" target="_blank" rel="noopener">
      ${LOGO(store)}
      <span class="price-info">
        <span class="store-name">${label}</span>
        <span class="price-row">${body}</span>
        ${low}
      </span>
      ${discount}
    </a>`;
}

function pricesHtml(g, data) {
  if (!auth.api) {
    return `<p class="hint">Preços indisponíveis nesta hospedagem.</p>`;
  }
  if (data === undefined) {
    return `<div class="price-card skeleton"></div><div class="price-card skeleton"></div>`;
  }
  if (data === null) return '<p class="hint error">Não foi possível carregar os preços agora.</p>';

  const steamUrl = safeUrl(g.steamUrl) || data.steam?.url;
  const epicUrl = safeUrl(g.epicUrl) || epicSearchUrl(g.name);
  const cards = [];
  if (steamUrl || data.steam) cards.push(priceCardHtml('steam', 'Steam', steamUrl || '#', data.steam, data.itad));
  cards.push(priceCardHtml('epic', 'Epic Games', data.epic?.url && !safeUrl(g.epicUrl) ? data.epic.url : epicUrl, data.epic, data.itad));

  const footer = data.historyLow
    ? `<p class="price-history">${ICON.trend}Menor preço já registrado: <strong>${formatMoney(data.historyLow)}</strong>
        ${data.itadUrl ? `· <a href="${esc(safeUrl(data.itadUrl))}" target="_blank" rel="noopener">histórico no IsThereAnyDeal</a>` : ''}</p>`
    : !data.itad
      ? '<p class="hint">Preço da Epic e histórico aparecem quando a chave do IsThereAnyDeal estiver configurada.</p>'
      : '';
  return cards.join('') + footer;
}

async function loadPrices(g) {
  const appid = steamAppId(g.steamUrl);
  const params = appid ? `appid=${appid}` : `title=${encodeURIComponent(g.name)}`;
  try {
    const data = await api(`/api/prices?${params}`);
    priceCache.set(g.key, data);
  } catch (e) {
    if (isOffline(e)) auth.api = false;
    priceCache.set(g.key, null);
  }
  if (state.detailId === g.id) {
    const el = $('#detail-prices');
    if (el) el.innerHTML = pricesHtml(g, priceCache.get(g.key));
  }
}

/* ownership */

function ownHtml(g) {
  if (!auth.user) {
    return `
      <div class="own-login">
        <p>Entre com a Steam para marcar que você tem este jogo.</p>
        <a class="btn btn-steam" href="/api/auth/login">${LOGO('steam')}Entrar com Steam</a>
      </div>`;
  }
  const { platforms, autoSteam } = myOwnership(g);
  return `
    <div class="own-toggles" role="group" aria-label="Plataformas em que você tem o jogo">
      ${PLATFORMS.map((p) => {
        const on = platforms.has(p.id);
        const locked = p.id === 'steam' && autoSteam;
        return `<button type="button" class="own-toggle ${p.id}" data-platform="${p.id}" aria-pressed="${on}"
          aria-label="Tenho na ${p.label}${locked ? ' (detectado na sua biblioteca Steam)' : ''}" ${locked ? 'disabled title="Detectado na sua biblioteca Steam"' : ''}>
          ${p.id === 'outra' ? ICON.gamepad : LOGO(p.id)}${p.label}${on ? ICON.check : ''}
        </button>`;
      }).join('')}
    </div>
    ${autoSteam ? '<p class="hint">Steam detectado automaticamente na sua biblioteca.</p>' : ''}`;
}

async function toggleOwnership(btn) {
  const g = findGame(state.detailId);
  if (!g || btn.disabled) return;
  const platform = btn.dataset.platform;
  const owned = btn.getAttribute('aria-pressed') !== 'true';
  btn.disabled = true;
  try {
    setMe(await api('/api/ownership', { method: 'POST', body: { key: g.key, platform, owned } }));
    await loadCounts();
    refreshAll();
    toast(owned ? `Marcado: você tem ${g.name}` : 'Marcação removida');
  } catch (e) {
    btn.disabled = false;
    if (e.status === 401) {
      auth.user = null;
      renderAccount();
      refreshAll();
      toast('Sua sessão expirou. Entre com a Steam de novo.');
    } else toast(isOffline(e) ? 'Sem conexão com o servidor' : e.message);
  }
}

async function loadOwners(g) {
  let owners = null;
  try {
    ({ owners } = await api(`/api/owners?key=${encodeURIComponent(g.key)}`));
  } catch {}
  if (state.detailId !== g.id) return;
  const list = $('#detail-owners');
  if (!list) return;
  $('#owners-count').textContent = owners?.length ? `(${owners.length})` : '';
  if (!owners) {
    list.innerHTML = '<li class="hint error">Não foi possível carregar.</li>';
    return;
  }
  if (!owners.length) {
    list.innerHTML = '<li class="hint">Ninguém marcou ainda. Seja o primeiro!</li>';
    return;
  }
  const meName = auth.user?.name;
  list.innerHTML = owners
    .map((o) => {
      const avatar = safeUrl(o.avatar);
      const profile = safeUrl(o.profileUrl);
      return `<li class="owner">
        <a href="${esc(profile)}" target="_blank" rel="noopener" class="owner-link">
          ${avatar ? `<img src="${esc(avatar)}" alt="" width="36" height="36" loading="lazy">` : '<span class="owner-avatar"></span>'}
          <span class="owner-name">${esc(o.name)}${o.name === meName ? ' <small>(você)</small>' : ''}</span>
        </a>
        <span class="owner-platforms">
          ${o.platforms
            .map((p) =>
              p.id === 'outra'
                ? `<span class="mini-plat" title="Outra plataforma">${ICON.gamepad}</span>`
                : `<span class="mini-plat ${p.id}" title="${p.id === 'steam' ? 'Steam' : 'Epic'}${p.auto ? ' (detectado)' : ''}">${LOGO(p.id)}</span>`,
            )
            .join('')}
        </span>
      </li>`;
    })
    .join('');
}

/* ---------------- account / counts ---------------- */

async function loadMe() {
  try {
    setMe(await api('/api/me'));
    auth.api = true;
  } catch (e) {
    if (isOffline(e)) auth.api = false;
    auth.user = null;
  }
}

async function loadCounts() {
  if (!auth.api) return;
  try {
    const keys = [...new Set(allGames().map((g) => g.key))];
    const { counts } = await api('/api/owners/counts', { method: 'POST', body: { keys } });
    auth.counts = counts;
  } catch {}
}

document.addEventListener('click', async (e) => {
  if (e.target.closest('#btn-user')) dlgMenu.showModal();

  if (e.target.closest('#btn-sync')) {
    const btn = e.target.closest('#btn-sync');
    btn.disabled = true;
    btn.textContent = 'Sincronizando…';
    try {
      setMe(await api('/api/me/sync', { method: 'POST', body: {} }));
      await loadCounts();
      renderAccount();
      syncToolbar();
      refreshAll();
      toast(auth.user.libraryVisible ? `Biblioteca sincronizada: ${auth.steamAppids.size} jogos` : 'Sua biblioteca Steam está privada');
    } catch (e2) {
      toast(e2.message);
      btn.disabled = false;
      btn.textContent = 'Sincronizar biblioteca';
    }
  }

  if (e.target.closest('#btn-logout')) {
    try {
      await api('/api/auth/logout', { method: 'POST', body: {} });
    } catch {}
    auth.user = null;
    auth.manual = [];
    auth.steamAppids = new Set();
    state.store.prefs.onlyOwned = false;
    saveStore();
    dlgMenu.close();
    renderAccount();
    syncToolbar();
    refreshAll();
    toast('Você saiu');
  }
});

